const FSC_WATERMARK_BASE64 = "data:image/png;base64," + "";

async function verifyHumanQuality(apiKey: string, imageUrl: string, referencePersonUrl?: string) {
  console.log("🔍 Running Human Quality Audit via Qwen VL...");
  try {
    const prompt = `You are a strict QA auditor for AI-generated fashion images.
Examine this image for human anatomy deformities.
Check for:
1. Broken or missing limbs
2. Extra or missing fingers/hands (must have 5 fingers per hand if visible)
3. Warped, melting, or mangled faces
4. Crossed, asymmetric, or unrealistic eyes
5. Severely deformed body proportions
6. BRAND PRESENCE: Is the model placed in a luxury environment? (Note: Exact spelling of logos is NOT required, as long as the environment feels premium and matches the requested studio style).
${referencePersonUrl ? `7. IDENTITY MATCH: Compare the generated person's face to the reference person's face (the second image provided). They should look like the same person or a very close lookalike. Fail ONLY if the generated person has a completely different ethnicity, skin tone, gender, or is an obvious mannequin.` : ""}

Return ONLY a valid JSON object in this format:
{
  "pass": true,
  "score": 95,
  "issues": ["Minor shadow on left arm"]
}`;
    
    const content: Array<{ image?: string; text?: string }> = [{ image: imageUrl }];
    if (referencePersonUrl) {
      content.push({ image: referencePersonUrl });
    }
    content.push({ text: prompt });

    const res = await fetch("https://dashscope-intl.aliyuncs.com/api/v1/services/aigc/multimodal-generation/generation", {
      method: "POST",
      headers: { "Authorization": `Bearer ${apiKey}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "qwen-vl-plus",
        input: {
          messages: [{
            role: "user",
            content: content
          }]
        }
      })
    });
    if (!res.ok) return { pass: true, score: 100, issues: [] };
    const data = await res.json();
    const rawContent = data.output?.choices?.[0]?.message?.content?.[0]?.text || "";
    const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const resData = JSON.parse(jsonMatch[0]);
      return { pass: resData.pass !== false && (resData.score >= 80), score: resData.score || 0, issues: resData.issues || [] };
    }
  } catch (err) {
    console.warn("Human quality verify error:", err);
  }
  return { pass: true, score: 100, issues: [] };
}

async function verifyClothingShape(apiKey: string, productImages: string[], generatedImageUrl: string) {
  console.log("🔍 Running Clothing Shape + Colour Audit via Qwen VL...");
  try {
    const prompt = `You are a strict fashion QA auditor. Compare the generated model image (last image) against the original product reference photo (first image).

Check ALL of the following:
1. COLOUR & SHADE MATCH: Is the garment colour or shade materially different? (e.g. powder light blue vs dark royal blue). A different shade or hue is an IMMEDIATE FAIL (pass: false).
2. TOP GARMENT CUT & COLLAR: Did a collared button-down shirt with chest flap pockets become a double-breasted blazer with lapels (or vice versa)? If the top garment cut or collar differs from Image 1, mark pass: false.
3. BOTTOM GARMENT SILHOUETTE: Did a skirt become trousers/pants, or trousers become a skirt? Marking pants on a skirt product (or vice versa) is an IMMEDIATE FAIL (pass: false).
4. POCKETS & BUTTON DETAILS: Are chest flap pockets, front button plackets, or waist gold buttons missing or replaced with blazer lapels? If key garment features are missing, mark pass: false.
5. FULL LENGTH FRAMING: Are the model's legs, feet, or shoes cut off at the thighs or knees? If cropped without showing full legs and feet on the floor, mark pass: false.

Return ONLY valid JSON — no markdown, no explanation outside JSON:
{"pass": true|false, "reason": "Brief explanation"}`;
    const res = await fetch("https://dashscope-intl.aliyuncs.com/api/v1/services/aigc/multimodal-generation/generation", {
      method: "POST",
      headers: { "Authorization": `Bearer ${apiKey}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "qwen-vl-plus",
        input: {
          messages: [{
            role: "user",
            content: [{ image: productImages[0] }, { image: generatedImageUrl }, { text: prompt }]
          }]
        }
      })
    });
    if (!res.ok) return { pass: true, reason: "" };
    const data = await res.json();
    const rawContent = data.output?.choices?.[0]?.message?.content?.[0]?.text || "";
    console.log(`[ClothingShapeAudit] Raw response: ${rawContent}`);
    const jsonMatch = rawContent.match(/\{[\s\S]*?\}/);
    if (jsonMatch) {
      const resData = JSON.parse(jsonMatch[0]);
      return { pass: resData.pass !== false, reason: resData.reason || "" };
    }
  } catch(err) { console.warn("[ClothingShapeAudit] Error:", err); }
  return { pass: true, reason: "" };
}

async function stockProtectionGate(supabaseClient: any, productId: string) {
  if (!productId || String(productId).startsWith("live_")) return { blocked: false };
  try {
    const { data } = await supabaseClient.from("products").select("stock_status, stock_quantity, status, vendor_id").eq("id", productId).maybeSingle();
    if (data) {
      // Vendor products bypass stock checks
      if (data.vendor_id) return { blocked: false };
      
      if (data.status === 'archived' || data.stock_status === 'out_of_stock' || (data.stock_quantity !== null && data.stock_quantity <= 0)) {
        return { blocked: true, reason: "Product currently unavailable." };
      }
    }
  } catch(e) {}
  return { blocked: false };
}

